.lac-ad-grid {
  --spacing-xxxxl: 96px;
  --size-l: 40px;
  --lac-ad-design-width: 1200px;
  --lac-ad-design-height: 800px;
  box-sizing: border-box;
  width: 64ch;
  display: grid;
  grid-template: "features" auto "features-actions" calc(var(--controls-size-default) + var(--spacing-xl)) "skip" auto "skip-actions" var(--controls-size-default) "image" auto/auto;
  gap: var(--spacing-xl);
  background-color: var(--background-color-primary);
  padding-top: var(--spacing-xxxl);
  padding-left: var(--spacing-l);
  padding-right: var(--spacing-l);
}

.lac-ad-grid[data-embedded] {
  padding-top: 0;
  margin: 0 auto;
}

.lac-ad-grid-features {
  grid-area: features;
  padding: var(--spacing-xl);
  padding-top: var(--spacing-xxl);
}

.lac-ad-grid-features-actions {
  grid-area: features-actions;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
  padding-bottom: var(--spacing-xxl);
}

.lac-ad-grid-skip {
  grid-area: skip;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
  padding-top: var(--spacing-xl);
}

.lac-ad-grid-skip-actions {
  grid-area: skip-actions;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
}

.lac-ad-grid-image {
  grid-area: image;
  display: none;
}

.lac-ad-grid-background {
  grid-row-start: 1;
  grid-row-end: 3;
  grid-column-start: 1;
  background-color: var(--background-color-secondary);
  border-radius: var(--border-radius-default);
}

@media (min-width: 1200px) {
  .lac-ad-grid {
    display: grid;
    grid-template: "features skip" auto "features-actions skip-actions" var(--controls-size-default) "image image" 360px/auto 42ch;
    gap: 0;
    width: var(--lac-ad-design-width);
    max-width: unset;
    height: var(--lac-ad-design-height);
    padding-left: 64px;
    padding-right: 64px;
    padding-top: var(--spacing-xxxl);
    border: solid var(--border-width-default) transparent;
    border-radius: var(--border-radius-l);
  }
  .lac-ad-grid[data-embedded] {
    border: none;
    padding-top: 0;
    padding-left: var(--spacing-xxxl);
    padding-right: var(--spacing-xxxl);
  }
  .lac-ad-grid-features {
    padding: var(--spacing-xxxl);
  }
  .lac-ad-grid-features-actions {
    padding-left: var(--spacing-xxxl);
    padding-right: var(--spacing-xxxl);
    padding-bottom: 0;
  }
  .lac-ad-grid-skip {
    padding-top: var(--spacing-xxxl);
    padding-left: var(--spacing-xxl);
    padding-right: var(--spacing-xxxl);
  }
  .lac-ad-grid-skip-actions {
    padding-left: var(--spacing-xxl);
  }
  .lac-ad-grid-image {
    display: block;
    grid-area: image;
    padding-top: var(--spacing-xxxl);
    border-bottom: solid var(--border-width-default) var(--border-color-strong);
  }
  .lac-ad-grid-background {
    grid-row-start: 1;
    grid-row-end: 4;
    grid-column-start: 1;
  }
}
@media (min-width: 1400px) and (min-height: 1000px) {
  .lac-ad-grid {
    border-color: var(--border-color-strong);
  }
  .lac-ad-grid-image {
    border-bottom: none;
  }
}
.lac-ad-features {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-xl);
  margin-left: var(--spacing-l);
}

@media (min-width: 1200px) {
  .lac-ad-features {
    grid-template-columns: 1fr 1fr;
  }
}
.lac-ad-feature-icon {
  flex: 0 0 var(--size-l);
  display: flex;
  width: var(--size-l);
  height: var(--size-l);
  align-items: center;
  justify-content: center;
  background-color: var(--background-color-info);
  border-radius: var(--border-radius-default);
}

.lac-ad-sign-up {
  padding-left: var(--spacing-xxxxl);
  padding-right: var(--spacing-xxxxl);
}

.lac-ad-screenshot {
  max-height: 100%;
  overflow: hidden;
}

.lac-ad-screenshot img {
  max-width: 100%;
}
