}

.carousel-indicators {
  cursor: pointer;
  display: flex;
  justify-content: center;
  padding-left: 0;
  margin-right: 15%;
  margin-left: 15%;
  list-style: none;
}
.carousel-indicators li {
  position: relative;
  flex: 0 1 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 7px;
  margin-left: 7px;
  background-color: var(--highlight-background-color-tertiary);
}
.carousel-indicators li::before {
  position: absolute;
  top: -10px;
  left: 0;
  display: inline-block;
  width: 100%;
  height: 10px;
  content: "";
}
.carousel-indicators li::after {
  position: absolute;
  bottom: -10px;
  left: 0;
  display: inline-block;
  width: 100%;
  height: 10px;
  content: "";
}
.carousel-indicators .active {
  background-color: var(--content-color-tertiary);
}

.carousel-caption {
  z-index: 10;
  padding: 10px 20px;
  color: var(--content-color-constant);
  text-align: center;
  cursor: default;
  -webkit-user-select: none;
  user-select: none;
}

