/**
 * Launch animation:
 *
 * - visible for screen >= 1200x800
 * - lower-aligned for 800 <= min-height <= 1000, otherwise centered
 * - left-aligned for 1200 <= min-width <= 1500, otherwise centered
 */
.home-page-signed-out {
  --hpso-design-width: 1400px;
  --hpso-design-height: 900px;
  background: var(--background-color-primary);
  height: 100vh;
  width: 100vw;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1200px) and (max-width: 1500px) and (min-height: 800px) {
  .home-page-signed-out {
    align-items: flex-start;
  }
}
@media (min-height: 800px) and (max-height: 1000px) and (min-width: 1200px) {
  .home-page-signed-out {
    justify-content: flex-end;
  }
}
.hpso-container {
  --hpso-animation-time: 0s;
  display: grid;
  grid-template: "form" auto/40ch;
}

@media (min-width: 1200px) and (min-height: 800px) {
  .hpso-container {
    --hpso-animation-time: 1.8s;
    width: 100vw;
    max-width: var(--hpso-design-width);
    height: 100vh;
    max-height: var(--hpso-design-height);
    grid-template: "animation form gutter" auto/5fr 40ch 1fr;
    gap: 48px;
  }
  .hpso-container[data-animation-disabled] {
    --hpso-animation-time: 0s;
  }
}
@media (min-width: 1500px) and (min-height: 800px) {
  .hpso-container {
    border-left: solid var(--border-width-default) var(--border-color-strong);
    border-right: solid var(--border-width-default) var(--border-color-strong);
  }
}
@media (min-width: 1500px) and (min-height: 900px) {
  .hpso-container {
    border-top: solid var(--border-width-default) var(--border-color-strong);
    border-top-left-radius: var(--border-radius-l);
    border-top-right-radius: var(--border-radius-l);
  }
}
@media (min-height: 1000px) and (min-width: 1200px) {
  .hpso-container {
    border-top: solid var(--border-width-default) var(--border-color-strong);
    border-bottom: solid var(--border-width-default) var(--border-color-strong);
  }
}
@media (min-height: 1000px) and (min-width: 1400px) {
  .hpso-container {
    border-right: solid var(--border-width-default) var(--border-color-strong);
    border-top-right-radius: var(--border-radius-l);
    border-bottom-right-radius: var(--border-radius-l);
  }
}
@media (min-width: 1500px) and (min-height: 1000px) {
  .hpso-container {
    border-radius: var(--border-radius-l);
  }
}
@media (prefers-reduced-motion) {
  .hpso-container {
    --hpso-animation-time: 0;
  }
}
/* Animation */
.hpso-animation {
  display: none;
  grid-area: animation;
  position: relative;
  align-self: flex-end;
  height: 100%;
  overflow: hidden;
}

@media (min-width: 1200px) and (min-height: 800px) {
  .hpso-animation {
    display: unset;
  }
}
@media (min-width: 1500px) and (min-height: 1000px) {
  .hpso-animation {
    border-radius: calc(var(--border-radius-l) - 1px);
  }
}
.hpso-animation svg {
  position: absolute;
  bottom: 0;
}

/* Form */
.hpso-form-container {
  grid-area: form;
  align-self: center;
  padding-inline: var(--spacing-l);
  padding-block: var(--spacing-xl);
  animation: hpso-fade-in var(--hpso-animation-time) ease;
}

.hpso-heading {
  line-height: 1.4;
}

.hpso-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-l);
}

.hpso-email-field {
  margin-top: var(--spacing-l);
  margin-bottom: var(--spacing-s);
}

.hpso-sign-in {
  align-self: center;
  margin-bottom: var(--spacing-xl) !important;
}

.hpso-skip {
  margin-top: var(--spacing-xxl);
}

@keyframes hpso-fade-in {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
/* OVERRIDE */
.app-requester:has(.home-page-signed-out) {
  min-width: unset !important;
  overflow-y: auto;
}

.lac-confirm {
  min-width: 100vw;
  min-height: 100vh;
