}

/* Backdrop (circles) */
.lac-confirm-backdrop {
  width: 100vw;
  height: 100vh;
  z-index: -1;
}

.lac-confirm-backdrop-right {
  background-color: transparent;
  width: 580px;
  height: 580px;
  border-radius: 580px;
  position: absolute;
  top: -280px;
  right: -280px;
  transition: background-color 250ms;
}

.lac-confirm-backdrop-left {
  background-color: transparent;
  width: 400px;
  height: 400px;
  border-radius: 400px;
  position: absolute;
  bottom: 0;
  left: -200px;
  transition: background-color 250ms;
}

@media (min-width: 1400px) and (min-height: 1000px) {
  .lac-confirm-backdrop-right {
    background-color: var(--background-color-brand);
  }
  .lac-confirm-backdrop-left {
    background-color: var(--background-color-warning);
  }
}
